public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_8e8b2d296e3549bb8bccf080c97fa27c.Models

<button class="reaction-badge" @onclick="OnClick" title="@string.Join(", ", Reaction.Users)">
    <span class="reaction-emoji">@Reaction.Emoji</span>
    <span class="reaction-count">@Reaction.Users.Count</span>
</button>

@code {
    [Parameter, EditorRequired] public Reaction Reaction { get; set; } = default!;
    [Parameter] public EventCallback OnClick { get; set; }
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    background: #f8f9fa;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background: #e2e6ea;
    border-color: #c0c0c0;
}

.reaction-emoji {
    font-size: 1rem;
}

.reaction-count {
    color: #555;
    font-weight: 500;
}

.emoji-picker {
    display: flex;
    gap: 4px;
    padding: 6px 8px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    position: absolute;
    z-index: 10;
    bottom: 100%;
    right: 0;
    margin-bottom: 4px;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    transition: background-color 0.15s;
    line-height: 1;
}

.emoji-option:hover {
    background: #f0f0f0;
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e0e0e0;
    background: #fff;
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-textarea:focus {
    border-color: #4a76a8;
}

.send-button {
    padding: 8px 20px;
    border: none;
    border-radius: 8px;
    background: #4a76a8;
    color: #fff;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    transition: background-color 0.15s;
}

.send-button:hover:not(:disabled) {
    background: #3a6090;
}

.send-button:disabled {
    background: #b0c4d8;
    cursor: not-allowed;
}

@using sv_8e8b2d296e3549bb8bccf080c97fa27c.Models

<div class="channel-item @(IsActive ? "active" : "")" @onclick="OnClick">
    <div class="channel-header-row">
        <span class="channel-name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="unread-badge">@Channel.UnreadCount</span>
        }
    </div>
    @if (!string.IsNullOrWhiteSpace(Channel.Description))
    {
        <div class="channel-description">@TruncateDescription(Channel.Description)</div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback OnClick { get; set; }

    private static string TruncateDescription(string description) =>
        description.Length > 40 ? string.Concat(description.AsSpan(0, 40), "…") : description;
}

.channel-item {
    padding: 10px 14px;
    cursor: pointer;
    border-radius: 6px;
    margin: 2px 8px;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background: rgba(255, 255, 255, 0.1);
}

.channel-item.active {
    background: rgba(255, 255, 255, 0.2);
}

.channel-header-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #e8eaed;
}

.channel-item.active .channel-name {
    color: #fff;
}

.unread-badge {
    background: #e74c3c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

.channel-description {
    font-size: 0.78rem;
    color: #adb5bd;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

