{"file_text": "@using sv_8e8b2d296e3549bb8bccf080c97fa27c.Models
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-list-container" @ref="scrollContainer">
    @if (IsLoadingMore)
    {
        <div class="loading-more">Loading older messages…</div>
    }
    @if (HasMore && !IsLoadingMore)
    {
        <button class="load-more-btn" @onclick="OnLoadMore">Load older messages</button>
    }
    @foreach (var message in Messages)
    {
        <MessageItem Message="message"
                     ThreadSummary="GetThreadSummary(message.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference scrollContainer;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<MessageList>? dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>("import", "./js/chat-scroll.js");
            dotNetRef = DotNetObjectReference.Create(this);
            await jsModule.InvokeVoidAsync("registerScrollHandler", scrollContainer, dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (!IsLoadingMore && HasMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    public async Task ScrollToBottomAsync()
    {
        if (jsModule is not null)
        {
            await jsModule.InvokeVoidAsync("scrollToBottom", scrollContainer);
        }
    }

    private ThreadSummary? GetThreadSummary(int messageId) =>
        ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);

    public async ValueTask DisposeAsync()
    {
        dotNetRef?.Dispose();
        if (jsModule is not null)
        {
            await jsModule.DisposeAsync();
        }
    }
}
