@using sv_8e8b2d296e3549bb8bccf080c97fa27c.Models

<aside class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="thread-close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <div class="thread-root-meta">
                <span class="thread-root-author">@RootMessage.Author</span>
                <span class="thread-root-time">@FormatRelativeTime(RootMessage.SentAt)</span>
            </div>
            <div class="thread-root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-replies">
            @if (Replies.Count > 0)
            {
                <div class="thread-reply-divider">
                    <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
                </div>
            }
            @foreach (var reply in Replies)
            {
                <div class="thread-reply-item">
                    <div class="thread-reply-meta">
                        <span class="thread-reply-author">@reply.Author</span>
                        <span class="thread-reply-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="thread-reply-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply in thread…" ButtonText="Reply" OnSend="OnReplySend" />
    }
</aside>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReplySend { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        return diff switch
        {
            { TotalMinutes: < 1 } => "just now",
            { TotalMinutes: < 60 } => $"{(int)diff.TotalMinutes} min ago",
            { TotalHours: < 24 } => $"{(int)diff.TotalHours}h ago",
            { TotalDays: < 7 } => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }
}

.thread-panel {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    background: #fff;
    border-left: 1px solid #e0e0e0;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    background: #fafafa;
}

.thread-header h6 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #1a1a1a;
}

.thread-close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #888;
    padding: 4px 8px;
    border-radius: 4px;
    transition: all 0.15s;
}

.thread-close-btn:hover {
    background: #eee;
    color: #333;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #eee;
    background: #f8f9fa;
}

.thread-root-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

.thread-root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1a1a1a;
}

.thread-root-time {
    font-size: 0.75rem;
    color: #888;
}

.thread-root-content {
    font-size: 0.9rem;
    color: #333;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-reply-divider {
    text-align: center;
    padding: 8px 0;
    font-size: 0.78rem;
    color: #999;
    border-bottom: 1px solid #eee;
    margin: 0 16px 8px;
}

.thread-reply-item {
    padding: 6px 16px;
}

.thread-reply-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.thread-reply-author {
    font-weight: 700;
    font-size: 0.88rem;
    color: #1a1a1a;
}

.thread-reply-time {
    font-size: 0.72rem;
    color: #888;
}

.thread-reply-content {
    font-size: 0.9rem;
    color: #333;
    white-space: pre-wrap;
    word-break: break-word;
}

