export function registerScrollHandler(element, dotNetRef) {
    if (!element) return;
    element.addEventListener('scroll', () => {
        if (element.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    });
}

export function scrollToBottom(element) {
    if (!element) return;
    element.scrollTop = element.scrollHeight;
}

@page "/chat"
@using sv_8e8b2d296e3549bb8bccf080c97fa27c.Models
@using sv_8e8b2d296e3549bb8bccf080c97fa27c.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(isThreadOpen ? "" : "expanded")">
        @if (selectedChannel is not null)
        {
            <div class="channel-header">
                <h5># @selectedChannel.Name</h5>
                <span class="channel-header-desc">@selectedChannel.Description</span>
            </div>

            <MessageList Messages="messages"
                         ThreadSummaries="threadSummaries"
                         IsLoadingMore="isLoadingMore"
                         HasMore="hasMoreMessages"
                         OnLoadMore="LoadOlderMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction" />

            <MessageInput Placeholder="@($"Message #{selectedChannel.Name}")"
                          OnSend="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnReplySend="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> channels = [];
    private int? selectedChannelId;
    private Channel? selectedChannel;

    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private int currentSkip;

    private bool isThreadOpen;
    private int? threadRootMessageId;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        if (selectedChannelId == channelId) return;

        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        currentSkip = 0;
        hasMoreMessages = true;
        messages = [];
        CloseThreadSync();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        hasMoreMessages = loaded.Count == PageSize;
        currentSkip = loaded.Count;

        ComputeThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore || !hasMoreMessages || selectedChannelId is null) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, currentSkip, PageSize);
        hasMoreMessages = older.Count == PageSize;
        currentSkip += older.Count;

        // Prepend older messages
        messages.InsertRange(0, older);
        ComputeThreadSummaries();
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessageId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        isThreadOpen = true;

        var thread = await ChatService.GetThreadAsync(rootMessageId);
        // First message in the thread response is the root; the rest are replies
        threadReplies = thread.Where(m => m.Id != rootMessageId).ToList();
    }

    private void CloseThreadSync()
    {
        isThreadOpen = false;
        threadRootMessageId = null;
        threadRootMessage = null;
        threadReplies = [];
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || threadRootMessageId is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessageId.Value);
        threadReplies.Add(reply);
        ComputeThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
    }

    private void ComputeThreadSummaries()
    {
        threadSummaries = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(
                g.Key,
                g.Count(),
                g.Max(m => m.SentAt)))
            .ToList();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
}

.chat-main.expanded {
    /* Takes remaining space when thread is closed */
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

.channel-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: #fafafa;
}

.channel-header h5 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a1a;
}

.channel-header-desc {
    font-size: 0.85rem;
    color: #777;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #aaa;
    font-size: 1.1rem;
}

export function registerScrollHandler(element, dotNetRef) {
    if (!element) return;
    element.addEventListener('scroll', () => {
        if (element.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    });
}

export function scrollToBottom(element) {
    if (!element) return;
    element.scrollTop = element.scrollHeight;
}

