+        CloseThreadSync();
+        return Task.CompletedTask;
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (selectedChannelId is null || threadRootMessageId is null) return;
+
+        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessageId.Value);
+        threadReplies.Add(reply);
+        ComputeThreadSummaries();
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+    }
+
+    private void ComputeThreadSummaries()
+    {
+        threadSummaries = messages
+            .Where(m => m.ReplyToId is not null)
+            .GroupBy(m => m.ReplyToId!.Value)
+            .Select(g => new ThreadSummary(
+                g.Key,
+                g.Count(),
+                g.Max(m => m.SentAt)))
+            .ToList();
+    }
+}
